insert into public.blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit, status, featured)
values
('hamming-you-and-your-research', 'You and Your Research', 'Transcript of Hamming''s 1986 Bellcore colloquium on why so few scientists do Nobel-class work: he argues that courage, working on important problems with the door open, and selling your results compound over a career far more than raw ability.', 'Richard Hamming', 'https://www.google.com/s2/favicons?domain=cs.virginia.edu&sz=128', 'How to Research', array['Research Careers','Problem Selection','Scientific Excellence','Classic Essay'], '50 min read', '1986-03-07', 'UVA Computer Science Archive', 'https://www.cs.virginia.edu/~robins/YouAndYourResearch.html', 'assets/img/covers/real/hamming-you-and-your-research.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('michael-nielsen-principles-of-effective-research', 'Principles of Effective Research', 'Nielsen''s 2004 essay splits effective research into self-development and creative work, offering concrete principles: work proactively rather than reactively, keep a vision you revisit, and develop your strengths as a problem-creator or problem-solver.', 'Michael Nielsen', 'https://www.google.com/s2/favicons?domain=michaelnielsen.org&sz=128', 'How to Research', array['Research Process','Self-Development','Problem Selection','Classic Essay'], '25 min read', '2004-07-27', 'michaelnielsen.org', 'https://michaelnielsen.org/blog/principles-of-effective-research/', 'assets/img/covers/real/michael-nielsen-principles-of-effective-research.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('keshav-how-to-read-a-paper', 'How to Read a Paper', 'Keshav''s widely translated two-page classic teaches the three-pass method — a five-minute bird''s-eye scan, an hour-long content pass, and a virtual re-implementation — and shows how to chain the passes into an efficient literature survey.', 'S. Keshav', 'https://www.google.com/s2/favicons?domain=svr-sk818-web.cl.cam.ac.uk&sz=128', 'How to Research', array['Paper Reading','Literature Review','Three-Pass Method','Research Skills'], '8 min read', '2007-07-01', 'University of Cambridge', 'https://svr-sk818-web.cl.cam.ac.uk/keshav/publications/htrap.html', 'assets/img/covers/real/keshav-how-to-read-a-paper.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('karpathy-survival-guide-to-a-phd', 'A Survival Guide to a PhD', 'Karpathy''s candid guide through the Stanford PhD: whether to do one at all, picking an adviser and problems at the research frontier, treating paper-writing as a craft to be studied, and surviving the psychological lows.', 'Andrej Karpathy', 'https://www.google.com/s2/favicons?domain=karpathy.github.io&sz=128', 'How to Research', array['PhD Advice','Adviser Selection','Paper Writing','Research Careers'], '35 min read', '2016-09-07', 'Andrej Karpathy Blog', 'https://karpathy.github.io/2016/09/07/phd/', 'assets/img/covers/real/karpathy-survival-guide-to-a-phd.jpg', 'Real cover from first-image', 'cover', 'published', false),
('john-schulman-opinionated-guide-ml-research', 'An Opinionated Guide to ML Research', 'Written for the OpenAI Fellows program, Schulman''s essay contrasts goal-driven with idea-driven research, prescribes reproducing papers to build skill, and treats research taste as something honed through deliberate feedback loops.', 'John Schulman', 'https://www.google.com/s2/favicons?domain=joschu.net&sz=128', 'How to Research', array['ML Research','Problem Selection','Research Taste','Mentoring'], '20 min read', '2020-01-24', 'joschu.net', 'http://joschu.net/blog/opinionated-guide-ml-research.html', 'assets/img/covers/real/john-schulman-opinionated-guide-ml-research.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('jacob-steinhardt-film-study-for-research', 'Film Study for Research', 'Steinhardt borrows two habits from elite athletes — film study and deliberate drills — and shows how researchers can replay how a result was actually produced, dissect papers and talks, and train isolated research skills on purpose.', 'Jacob Steinhardt', 'https://www.google.com/s2/favicons?domain=jsteinhardt.stat.berkeley.edu&sz=128', 'How to Research', array['Deliberate Practice','Research Training','Skill Building','Mentoring'], '10 min read', '2021-06-28', 'Jacob Steinhardt', 'https://jsteinhardt.stat.berkeley.edu/blog/film-study', 'assets/img/covers/real/jacob-steinhardt-film-study-for-research.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('distill-research-debt', 'Research Debt', 'Olah and Carter diagnose ''research debt'' — the accumulated interpretive labor of undigested ideas, bad abstractions, and noise that walls off a field — and argue that distillation is serious research work deserving first-class credit.', 'Chris Olah and Shan Carter', 'https://www.google.com/s2/favicons?domain=distill.pub&sz=128', 'How to Research', array['Research Distillation','Scientific Communication','Interpretive Labor','Field Building'], '12 min read', '2017-03-22', 'Distill', 'https://distill.pub/2017/research-debt/', 'assets/img/covers/real/distill-research-debt.jpg', 'Real cover from og:image', 'cover', 'published', false),
('colah-research-taste-exercises', 'Research Taste Exercises', 'A rough note offering five concrete exercises for developing research taste — necessary because real feedback on whether an idea was good arrives only a few times a year — along with three failure modes to avoid.', 'Christopher Olah', 'https://www.google.com/s2/favicons?domain=colah.github.io&sz=128', 'How to Research', array['Research Taste','Deliberate Practice','Research Judgment','Problem Selection'], '8 min read', '2021-01-09', 'colah''s blog', 'https://colah.github.io/notes/taste/', 'assets/img/covers/real/colah-research-taste-exercises.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('jason-wei-practicing-ai-research', 'Practicing AI research', 'Jason Wei decomposes AI research into four trainable skills — idea conception and selection, experiment design and execution, paper writing, and maximizing impact — and gives practical habits for improving each through practice.', 'Jason Wei', 'https://www.google.com/s2/favicons?domain=jasonwei.net&sz=128', 'How to Research', array['AI Research','Research Practice','Paper Writing','Career Growth'], '12 min read', '2023-02-07', 'Jason Wei Blog', 'https://www.jasonwei.net/blog/practicing-ai-research', 'assets/img/covers/real/jason-wei-practicing-ai-research.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('eugene-yan-choosing-problems', 'Choosing Problems in Data Science and Machine Learning', 'Eugene Yan converts problem selection into explicit trade-offs — short versus long-term gain, incremental versus disruptive innovation, resume-driven versus impact-driven development — for deciding which ML problems deserve your time.', 'Eugene Yan', 'https://www.google.com/s2/favicons?domain=eugeneyan.com&sz=128', 'How to Research', array['Problem Selection','Data Science','Prioritization','Career Growth'], '12 min read', '2021-03-21', 'eugeneyan.com', 'https://eugeneyan.com/writing/how-to-choose-problems/', 'assets/img/covers/real/eugene-yan-choosing-problems.jpg', 'Real cover from og:image', 'cover', 'published', false),
('matt-might-illustrated-guide-to-phd', 'The Illustrated Guide to a Ph.D.', 'Matt Might''s circle-of-knowledge drawings compress the doctoral journey into a handful of pictures: years of study buy you a tiny dent in the boundary of human knowledge — so keep pushing.', 'Matt Might', 'https://www.google.com/s2/favicons?domain=matt.might.net&sz=128', 'How to Research', array['PhD Advice','Visual Explanation','Research Careers','Classic Essay'], '3 min read', '2010-01-01', 'matt.might.net', 'https://matt.might.net/articles/phd-school-in-pictures/', 'assets/img/covers/real/matt-might-illustrated-guide-to-phd.jpg', 'Real cover from first-image', 'cover', 'published', false),
('terence-tao-partial-progress', 'On the importance of partial progress', 'Tao explains why researchers must value partial progress: failed attempts and solved toy cases cost nothing to combine later, and they localize exactly where the remaining difficulty of a problem lives.', 'Terence Tao', 'https://www.google.com/s2/favicons?domain=terrytao.wordpress.com&sz=128', 'How to Research', array['Problem Solving','Partial Progress','Mathematical Research','Career Advice'], '6 min read', '2012-07-17', 'What''s new (Terence Tao)', 'https://terrytao.wordpress.com/career-advice/on-the-importance-of-partial-progress/', 'assets/img/covers/real/terence-tao-partial-progress.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('terence-tao-learn-and-relearn-your-field', 'Learn and relearn your field', 'Starting from Pólya''s dictum that no problem is ever exhausted, Tao lists ways to keep re-learning your own field — alternate proofs, dropped hypotheses, model examples, and asking why each result is true — until understanding becomes generative.', 'Terence Tao', 'https://www.google.com/s2/favicons?domain=terrytao.wordpress.com&sz=128', 'How to Research', array['Deep Understanding','Learning Strategy','Mathematical Research','Career Advice'], '5 min read', '2007-05-06', 'What''s new (Terence Tao)', 'https://terrytao.wordpress.com/career-advice/learn-and-relearn-your-field/', 'assets/img/covers/real/terence-tao-learn-and-relearn-your-field.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('google-brain-team-approach-to-research', 'The Google Brain Team''s Approach to Research', 'Jeff Dean describes how Google Brain organizes research as a portfolio across timescales, pairing long-term open-ended work with product collaborations, and measuring success through papers, open tools, and the researchers it trains.', 'Jeff Dean', 'https://www.google.com/s2/favicons?domain=research.google&sz=128', 'How to Research', array['Research Strategy','Industrial Research','Google Brain','Research Management'], '8 min read', '2017-09-13', 'Google Research Blog', 'https://research.google/blog/the-google-brain-teams-approach-to-research/', 'assets/img/covers/real/google-brain-team-approach-to-research.jpg', 'Real cover from og:image', 'cover', 'published', false),
('metr-changing-developer-productivity-experiment-design', 'We are Changing our Developer Productivity Experiment Design', 'METR publicly diagnoses why its second developer-productivity RCT became unreliable — developers increasingly refused to work without AI, biasing the speedup estimate — and details the redesigned experiment that addresses the selection effect.', 'Joel Becker, Nate Rush, Tom Cunningham, David Rein, and Khalid Mahamud', 'https://www.google.com/s2/favicons?domain=metr.org&sz=128', 'Research Craft', array['Experiment Design','Selection Effects','Developer Productivity','Research Integrity'], '8 min read', '2026-02-24', 'METR Blog', 'https://metr.org/blog/2026-02-24-uplift-update/', 'assets/img/covers/real/metr-changing-developer-productivity-experiment-design.png', 'Real cover from og:image', 'cover', 'published', false),
('hamel-husain-hard-to-eval-is-a-product-smell', '"It''s Hard to Eval" Is a Product Smell', 'Hamel Husain argues that when an AI product is hard to evaluate, the product itself is misdesigned: outputs users cannot verify are outputs builders cannot eval, so verifiability should be a first-class design constraint.', 'Hamel Husain', 'https://www.google.com/s2/favicons?domain=hamel.dev&sz=128', 'Research Craft', array['Evals','Product Design','Verifiability','AI Products'], '10 min read', '2026-06-29', 'Hamel''s Blog', 'https://hamel.dev/blog/posts/eval-smell/', 'assets/img/covers/real/hamel-husain-hard-to-eval-is-a-product-smell.png', 'Real cover from og:image', 'cover', 'published', false),
('google-deep-learning-tuning-playbook', 'Deep Learning Tuning Playbook', 'Godbole, Dahl, Gilmer, Shallue, and Nado codify Google Brain''s hyperparameter-tuning practice into an explicit protocol: start from a baseline, separate scientific from nuisance hyperparameters, and iterate through deliberately designed tuning rounds.', 'Varun Godbole, George E. Dahl, Justin Gilmer, Christopher J. Shallue, and Zachary Nado', 'https://www.google.com/s2/favicons?domain=developers.google.com&sz=128', 'Research Craft', array['Hyperparameter Tuning','Deep Learning','Experimental Protocol','Best Practices'], '60 min read', '2023-01-19', 'Google for Developers', 'https://developers.google.com/machine-learning/guides/deep-learning-tuning-playbook', 'assets/img/covers/real/google-deep-learning-tuning-playbook.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('google-rules-of-machine-learning', 'Rules of Machine Learning: Best Practices for ML Engineering', 'Zinkevich''s 43 rules stage ML engineering discipline from ''launch without ML if you can'' through feature engineering to refinement, with hard-won guidance on metrics, training-serving skew, and keeping the first pipeline simple.', 'Martin Zinkevich', 'https://www.google.com/s2/favicons?domain=developers.google.com&sz=128', 'Research Craft', array['ML Engineering','Best Practices','Training-Serving Skew','Pipelines'], '45 min read', '2018-01-01', 'Google for Developers', 'https://developers.google.com/machine-learning/guides/rules-of-ml/', 'assets/img/covers/real/google-rules-of-machine-learning.png', 'Real cover from manual:original-page-screenshot', 'cover', 'published', false),
('eugene-yan-how-to-test-machine-learning', 'How to Test Machine Learning Code and Systems', 'Eugene Yan separates ML testing into checks for correct implementation, expected learned behaviour, and satisfactory performance, with runnable pre-train and post-train tests for invariance, directional expectations, and gradient sanity.', 'Eugene Yan', 'https://www.google.com/s2/favicons?domain=eugeneyan.com&sz=128', 'Research Craft', array['ML Testing','Reproducibility','Model Evaluation','Engineering Practice'], '15 min read', '2020-09-06', 'eugeneyan.com', 'https://eugeneyan.com/writing/testing-ml/', 'assets/img/covers/real/eugene-yan-how-to-test-machine-learning.jpg', 'Real cover from og:image', 'cover', 'published', false),
('eugene-yan-maintaining-machine-learning-in-production', 'A Practical Guide to Maintaining Machine Learning in Production', 'A checklist-driven tour of the unglamorous half of ML — monitoring data quality after deployment, deciding retraining cadence, breaking feedback loops, and paying down the pipeline complexity that accumulates in production systems.', 'Eugene Yan', 'https://www.google.com/s2/favicons?domain=eugeneyan.com&sz=128', 'Research Craft', array['MLOps','Production ML','Monitoring','Technical Debt'], '15 min read', '2020-05-25', 'eugeneyan.com', 'https://eugeneyan.com/writing/practical-guide-to-maintaining-machine-learning/', 'assets/img/covers/real/eugene-yan-maintaining-machine-learning-in-production.jpg', 'Real cover from og:image', 'cover', 'published', false),
('cmu-ml-blog-reproducibility', '5 – Reproducibility', 'From ML@CMU''s research-practice series: a taxonomy of reproducibility failures in machine learning and a checklist covering data and code release, random seeds, run counts, and variance reporting that authors and reviewers can apply directly.', 'Zihao Ding, Aniketh Reddy, and Aparna Joshi', 'https://www.google.com/s2/favicons?domain=blog.ml.cmu.edu&sz=128', 'Research Craft', array['Reproducibility','Research Methodology','Variance Reporting','Open Science'], '12 min read', '2020-08-31', 'ML@CMU Blog', 'https://blog.ml.cmu.edu/2020/08/31/5-reproducibility/', 'assets/img/covers/real/cmu-ml-blog-reproducibility.png', 'Real cover from og:image', 'cover', 'published', false),
('distill-how-to-use-tsne-effectively', 'How to Use t-SNE Effectively', 'Wattenberg, Viégas, and Johnson''s interactive Distill essay demonstrates how perplexity and iteration count reshape t-SNE plots, and why cluster sizes and inter-cluster distances in the projection usually cannot be trusted.', 'Martin Wattenberg, Fernanda Viégas, and Ian Johnson', 'https://www.google.com/s2/favicons?domain=distill.pub&sz=128', 'Research Craft', array['t-SNE','Visualization','Dimensionality Reduction','Interpretation Pitfalls'], '12 min read', '2016-10-13', 'Distill', 'https://distill.pub/2016/misread-tsne/', 'assets/img/covers/real/distill-how-to-use-tsne-effectively.jpg', 'Real cover from og:image', 'cover', 'published', false),
('openai-how-evals-drive-the-next-chapter-in-ai', 'How evals drive the next chapter in AI for businesses', 'OpenAI''s Applied Evals and Economic Research teams argue that contextual evals — specified, measured, and improved against a specific workflow — are what turn frontier model capability into dependable deployed systems.', 'OpenAI', 'https://www.google.com/s2/favicons?domain=openai.com&sz=128', 'Research Craft', array['Evals','Contextual Evaluation','AI Deployment','Measurement'], '10 min read', '2025-11-19', 'OpenAI', 'https://openai.com/index/evals-drive-next-chapter-of-ai/', 'assets/img/covers/real/openai-how-evals-drive-the-next-chapter-in-ai.png', 'Real cover from og:image', 'cover', 'published', false),
('epoch-ai-can-ai-scaling-continue-through-2030', 'Can AI scaling continue through 2030?', 'Epoch AI quantifies four constraints on continued scale-up — power, chip manufacturing, data scarcity, and the latency wall — and concludes that training runs of 2e29 FLOP, a GPT-2-to-GPT-4-sized leap beyond today, look feasible by 2030.', 'Jaime Sevilla et al.', 'https://www.google.com/s2/favicons?domain=epoch.ai&sz=128', 'Frontier', array['Scaling','Compute','Power Constraints','AI Forecasting'], '40 min read', '2024-08-20', 'Epoch AI', 'https://epoch.ai/publications/can-ai-scaling-continue-through-2030', 'assets/img/covers/real/epoch-ai-can-ai-scaling-continue-through-2030.png', 'Real cover from og:image', 'cover', 'published', false),
('epoch-ai-have-ai-capabilities-accelerated', 'Have AI Capabilities Accelerated?', 'Epoch AI fits trend breaks to four capability metrics to test whether AI progress has sped up: three of the four show strong evidence of acceleration, driven primarily by the rise of reasoning models.', 'Jean-Stanislas Denain et al.', 'https://www.google.com/s2/favicons?domain=epoch.ai&sz=128', 'Frontier', array['AI Progress','Capability Trends','Reasoning Models','Trend Analysis'], '20 min read', '2026-04-16', 'Epoch AI', 'https://epoch.ai/publications/have-ai-capabilities-accelerated', 'assets/img/covers/real/epoch-ai-have-ai-capabilities-accelerated.png', 'Real cover from og:image', 'cover', 'published', false),
('epoch-ai-training-compute-grows-4-5x-per-year', 'Training compute of frontier AI models grows by 4-5x per year', 'Using Epoch''s expanded database of notable models, this report establishes that frontier training compute has grown 4-5x per year since 2010, a rate that holds across frontier models, language models, and leading labs alike.', 'Jaime Sevilla et al.', 'https://www.google.com/s2/favicons?domain=epoch.ai&sz=128', 'Frontier', array['Training Compute','Scaling Trends','Frontier Models','Data Analysis'], '12 min read', '2024-05-28', 'Epoch AI', 'https://epoch.ai/publications/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year', 'assets/img/covers/real/epoch-ai-training-compute-grows-4-5x-per-year.png', 'Real cover from og:image', 'cover', 'published', false),
('epoch-ai-power-demands-of-frontier-ai-training', 'How much power will frontier AI training demand in 2030?', 'Josh You projects the power demands of frontier training: draw is growing by more than 2x per year and is on trend to require multiple gigawatts — and eventually distributed, multi-site runs — by 2030.', 'Josh You', 'https://www.google.com/s2/favicons?domain=epoch.ai&sz=128', 'Frontier', array['Power Demand','AI Infrastructure','Data Centers','Forecasting'], '15 min read', '2025-08-11', 'Epoch AI', 'https://epoch.ai/publications/power-demands-of-frontier-ai-training', 'assets/img/covers/real/epoch-ai-power-demands-of-frontier-ai-training.png', 'Real cover from og:image', 'cover', 'published', false),
('colin-raffel-when-will-language-models-be-good-enough', 'When will language models be good enough?', 'Colin Raffel uses the parable of the Boeing 747 and supersonic flight to ask whether language models are nearing a ''good enough'' plateau, where cost, reliability, and convenience — not peak capability — determine which systems endure.', 'Colin Raffel', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Frontier', array['AI Progress','Capability Plateaus','Language Models','Research Perspective'], '7 min read', '2026-07-16', 'Hugging Face Blog', 'https://huggingface.co/blog/craffel/when-will-language-models-be-good-enough', 'assets/img/covers/real/colin-raffel-when-will-language-models-be-good-enough.png', 'Real cover from og:image', 'cover', 'published', false),
('mishig-two-years-of-local-ai-on-a-laptop', 'Two Years of Local AI on a Laptop: When Open Models Outpaced Moore''s Law', 'With MacBook memory stuck at 128 GB from 2024 to 2026, this analysis tracks six snapshots of the best open model runnable on one laptop, showing local intelligence scores jumping from 3 to 50 through sparse MoE and quantization rather than hardware.', 'Mishig Davaadorj', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Frontier', array['Open Models','Local Inference','Quantization','Capability Trends'], '15 min read', '2026-05-11', 'Hugging Face Blog', 'https://huggingface.co/blog/mishig/local-moores-law', 'assets/img/covers/real/mishig-two-years-of-local-ai-on-a-laptop.png', 'Real cover from og:image', 'cover', 'published', false),
('mistral-robostral-navigate', 'Robostral Navigate: single-camera AI navigation', 'Mistral''s first embodied model: an 8B network that follows plain-language routes from a single RGB camera, hitting 76.6% on R2R-CE validation unseen — beating depth- and multi-camera systems — with pointing-based actions and online reinforcement learning.', 'Mistral AI', 'https://www.google.com/s2/favicons?domain=mistral.ai&sz=128', 'Frontier', array['Embodied AI','Robot Navigation','Vision-Language Models','Reinforcement Learning'], '8 min read', '2026-07-08', 'Mistral AI News', 'https://mistral.ai/news/robostral-navigate/', 'assets/img/covers/real/mistral-robostral-navigate.jpg', 'Real cover from og:image', 'cover', 'published', false),
('stanford-hai-2026-ai-index-report', 'The 2026 AI Index Report', 'The ninth AI Index compiles independently sourced data across nine chapters — from R&D and technical performance to policy and public opinion — documenting a year in which capabilities advanced faster than our ability to measure and manage them.', 'Stanford HAI', 'https://www.google.com/s2/favicons?domain=hai.stanford.edu&sz=128', 'Frontier', array['AI Index','Annual Report','AI Policy','Measurement'], '20 min read', '2026-04-13', 'Stanford HAI', 'https://hai.stanford.edu/ai-index/2026-ai-index-report', 'assets/img/covers/real/stanford-hai-2026-ai-index-report.jpg', 'Real cover from og:image', 'cover', 'published', false),
('international-ai-safety-report-2026', 'International AI Safety Report 2026', 'The second International AI Safety Report, led by Yoshua Bengio with over 100 experts and backed by more than 30 countries, synthesizes the scientific evidence on general-purpose AI capabilities and risks — the largest global collaboration on AI safety to date.', 'Yoshua Bengio et al.', 'https://www.google.com/s2/favicons?domain=internationalaisafetyreport.org&sz=128', 'Frontier', array['AI Safety','International Governance','Scientific Assessment','General-Purpose AI'], '30 min read', '2026-02-03', 'International AI Safety Report', 'https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026', 'assets/img/covers/real/international-ai-safety-report-2026.jpg', 'Real cover from og:image', 'cover', 'published', false),
('uk-aisi-frontier-ai-trends-report', 'Frontier AI Trends Report', 'AISI''s first public trends report aggregates two years of evaluations across more than 30 frontier systems, finding some capabilities doubling every eight months, cyber task success rising from 10% to 50%, and universal jailbreaks in every system tested.', 'UK AI Security Institute', 'https://www.google.com/s2/favicons?domain=aisi.gov.uk&sz=128', 'Frontier', array['Frontier Evals','Capability Trends','AI Security','Government Research'], '25 min read', '2025-12-18', 'UK AISI', 'https://www.aisi.gov.uk/frontier-ai-trends-report', 'assets/img/covers/real/uk-aisi-frontier-ai-trends-report.webp', 'Real cover from first-image', 'cover', 'published', false)
